-- 474: Original BrillaPrep Cambridge A-Level Biology (9700) Ecology and Nutrient Cycles multiple-choice questions (part 2) (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_474_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_474_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_ecology_s2_007', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a eutrophic lake, which event is the direct cause of large-scale fish deaths?', 'multiple_choice', NULL, '["A. Direct poisoning of fish tissues by nitrate ions from the fertiliser","B. Algal cells physically blocking the gills of the fish","C. Depletion of dissolved oxygen by the respiration of huge populations of decomposer bacteria feeding on dead algae","D. Decomposer bacteria feeding directly on the living fish"]', 'C', 'Nitrate enrichment triggers an algal bloom; when the algae die, saprotrophic bacteria multiply and respire aerobically as they decompose the biomass, stripping dissolved oxygen from the water (a high biological oxygen demand) until fish suffocate. Nitrate at these concentrations is not acutely toxic to fish, gill blockage by algal cells is not the mechanism, and decomposers feed on dead organic matter, not on living fish. Therefore the correct answer is C: Depletion of dissolved oxygen by the respiration of huge populations of decomposer bacteria feeding on dead algae.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_008', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Why do persistent pesticides such as DDT reach their highest concentrations in top carnivores?', 'multiple_choice', NULL, '["A. Top carnivores drink more contaminated water than organisms at lower trophic levels","B. DDT becomes progressively more water-soluble as it passes up the food chain","C. The faster metabolism of top carnivores manufactures DDT from harmless precursors","D. DDT is fat-soluble and cannot be broken down or excreted, so it accumulates in body fat and its concentration increases at each successive trophic level"]', 'D', 'Persistent organic pollutants such as DDT resist biodegradation and dissolve in lipids rather than water, so an organism stores every dose it ever consumes in its fatty tissues. Because each trophic level must eat many organisms from the level below, the stored dose is passed up and concentrated — biomagnification — leaving top carnivores such as fish eagles with the highest tissue concentrations. DDT is not manufactured by any animal, and it does not become more soluble as it moves up the chain. Therefore the correct answer is D: DDT is fat-soluble and cannot be broken down or excreted, so it accumulates in body fat and its concentration increases at each successive trophic level.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_009', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In an oak woodland, the pyramid of numbers is inverted because one tree supports thousands of aphids, yet the pyramid of energy for the same community is never inverted. Which statement explains this?', 'multiple_choice', NULL, '["A. Energy is always lost from the ecosystem between trophic levels, mainly as respiratory heat, so the rate of energy flow through each level must decrease regardless of the size or number of individual organisms","B. Large producers such as trees are excluded from pyramids of energy","C. Insects do not respire, so their energy is not counted in the pyramid","D. The pyramid of energy is inverted whenever the pyramid of numbers is inverted"]', 'A', 'Pyramids of numbers count individuals and ignore size, so a single large producer can support many small consumers and invert the pattern. A pyramid of energy plots the rate of energy flow (kJ m⁻² yr⁻¹) through each trophic level; because respiration, excretion and undigested material always remove energy between levels, each bar must be smaller than the one below, so the pyramid can never be inverted. Insects respire like all animals, trees supply the energy that defines the base bar, and the two pyramids describe different quantities that need not share a shape. Therefore the correct answer is A: Energy is always lost from the ecosystem between trophic levels, mainly as respiratory heat, so the rate of energy flow through each level must decrease regardless of the size or number of individual organisms.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_010', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a mark–release–recapture study of a tilapia population, some of the marks wear off before the second sample is taken. How will this affect the population estimate?', 'multiple_choice', NULL, '["A. The estimate will be too low, because fewer marked fish are recaptured","B. The estimate will be too high, because fewer marked fish are recaptured than expected, reducing the denominator in N = (n1 × n2) ÷ m","C. The estimate is unaffected, because the marks are irrelevant after release","D. The estimate will be too high, because more unmarked fish are caught in the second sample"]', 'B', 'The Lincoln index assumes marks are not lost between samples. If marks wear off, m (the number of marked fish in the second sample) is smaller than it should be; since m is the denominator of N = (n1 × n2) ÷ m, dividing by too small a value inflates the estimate. The number of unmarked fish caught does not compensate in the formula, and the marks certainly remain relevant after release — the whole method depends on recognising them. Therefore the correct answer is B: The estimate will be too high, because fewer marked fish are recaptured than expected, reducing the denominator in N = (n1 × n2) ÷ m.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Analyse', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_011', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A farmer ploughs a cowpea crop into the soil as green manure. Which sequence correctly explains the rise in soil nitrate over the following months?', 'multiple_choice', NULL, '["A. Rhizobium in the dead nodules continues to fix nitrogen gas directly into nitrate","B. Denitrifying bacteria convert the organic nitrogen straight into nitrate","C. Decomposers break down the plant proteins and release ammonium ions (ammonification), then nitrifying bacteria oxidise the ammonium ions to nitrate","D. The living legume roots excrete nitrate ions after the crop is ploughed in"]', 'C', 'Once ploughed in, the crop — including its nitrogen-rich root nodules — is dead organic matter. Saprotrophic bacteria and fungi decompose its proteins, releasing ammonium ions (ammonification); Nitrosomonas and Nitrobacter then oxidise the ammonium ions to nitrite and nitrate (nitrification), enriching the soil for the next crop. Nitrogen fixation stops when the nodules die, denitrification removes nitrate from the soil rather than producing it, and dead roots excrete nothing. Therefore the correct answer is C: Decomposers break down the plant proteins and release ammonium ions (ammonification), then nitrifying bacteria oxidise the ammonium ions to nitrate.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_474_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_474_guard (valid INTEGER NOT NULL CHECK (valid = 1));
